-<style>
-h1{font-size:clamp(2rem,5.5vw,4rem);font-weight:800;letter-spacing:-1.5px;line-height:1.08;margin-bottom:1rem;color:#fff}
-h2{font-size:clamp(1.5rem,3.5vw,2.4rem);font-weight:700;letter-spacing:-0.5px;line-height:1.2;margin-bottom:0.8rem;color:#fff}
-.exec{background:rgba(11,17,26,0.88);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border:1px solid rgba(34,211,238,0.12);border-radius:14px;padding:1.8rem;margin:2rem 0;text-align:left}
-.exec h3{color:var(--ac);font-size:0.78rem;text-transform:uppercase;letter-spacing:1px;margin-bottom:1rem}
-.exec li{margin:0.5rem 0;font-size:0.85rem;line-height:1.6;color:var(--t2);list-style:none;padding-left:1.5rem;position:relative}
-.exec li::before{content:'';position:absolute;left:0;top:0.55rem;width:8px;height:8px;border-radius:50%;background:var(--ac)}
-.exec strong{color:var(--t)}
-.card .cname{font-size:0.75rem;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:0.5rem;color:var(--t)}
-.card .cval{font-size:1.4rem;font-weight:800;color:var(--ac)}
-.card .cval.amber{color:var(--am)}
-.card .csub{font-size:0.72rem;color:var(--t2);margin:0.3rem 0}
-.card .ctag{display:inline-block;padding:0.15rem 0.5rem;border-radius:4px;font-size:0.62rem;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;margin:0.3rem 0;background:rgba(34,211,238,0.08);color:var(--ac);border:1px solid rgba(34,211,238,0.15)}
-.card .ctag.amber{background:rgba(251,191,36,0.08);color:var(--am);border:1px solid rgba(251,191,36,0.15)}
-.card .ctag.cyan{background:rgba(34,211,238,0.08);color:var(--cy);border:1px solid rgba(34,211,238,0.15)}
-.wtm{background:var(--bg4);border-left:3px solid var(--ac);border-radius:0 10px 10px 0;padding:1rem 1.2rem;margin:1rem 0;font-size:0.85rem;color:var(--t2);line-height:1.7}
-.wtm strong{color:var(--t)}
-.constraints{display:grid;grid-template-columns:1fr;gap:0.3rem;margin:1rem 0;max-width:650px;margin-left:auto;margin-right:auto}
-.cr{display:grid;grid-template-columns:1fr 1.5fr 1.5fr;gap:0.5rem;align-items:center;padding:0.45rem 0.8rem;background:var(--bg3);border-radius:8px;border:1px solid var(--b);font-size:0.78rem}
-.cr.head{background:var(--bg4);font-weight:600;font-size:0.68rem;text-transform:uppercase;letter-spacing:0.5px;color:var(--t2)}
-.cr .nm{font-weight:500}.cr .fl{font-family:'JetBrains Mono',monospace;font-size:0.68rem;color:var(--t3)}.cr .ck{text-align:center}
-.rules-grid{display:grid;grid-template-columns:1fr;gap:0.5rem;max-width:720px;margin:1rem auto}
-.rule{display:flex;align-items:flex-start;gap:1.2rem;padding:0.9rem 1.2rem;background:var(--bg3);border:1px solid var(--b);border-radius:10px;font-size:0.85rem;text-align:left}
-.rule .rn{font-size:1.6rem;font-weight:800;min-width:2rem;text-align:center;flex-shrink:0;color:var(--ac)}
-.rule .rn.amber{color:var(--am)}.rule .rn.purple{color:#a78bfa}
-.rule .rt{flex:1}.rule .rt strong{color:var(--t)}.rule .rt .rm{display:block;font-size:0.72rem;color:var(--t3);margin-top:0.2rem}
-.rule .rt .badge-ext{display:inline-block;padding:0.1rem 0.5rem;border-radius:4px;font-size:0.62rem;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;margin-top:0.3rem;background:rgba(251,191,36,0.08);color:var(--am);border:1px solid rgba(251,191,36,0.2)}
-.badge-mod{background:rgba(245,158,11,0.12);color:var(--am);font-size:0.6rem;padding:1px 6px;border-radius:3px;margin-left:4px}
-.params{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:0.6rem;max-width:780px;margin:1rem auto}
-.param{background:var(--bg3);border:1px solid var(--b);border-radius:10px;padding:0.9rem 1rem;text-align:left}
-.param .psym{font-family:'JetBrains Mono',monospace;font-size:0.78rem;font-weight:700;color:var(--ac);margin-bottom:0.2rem}
-.param .pname{font-size:0.72rem;color:var(--t2)}
-.doors{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin:1rem 0}
-.door{background:var(--bg3);border:1px solid var(--b);border-radius:12px;padding:1.3rem;text-align:left}
-.door.tw{border-left:3px solid var(--ac)}.door.ow{border-left:3px solid var(--am)}
-.door h3{font-size:0.9rem;margin-bottom:0.5rem}.door.tw h3{color:var(--ac)}.door.ow h3{color:var(--am)}
-.door p,.door li{font-size:0.82rem;color:var(--t2);line-height:1.6;margin:0.3rem 0}.door ul{list-style:none;padding:0}.door li::before{content:'\2192 ';color:var(--t3)}
-.roi-calc{background:rgba(11,17,26,0.88);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border:1px solid rgba(34,211,238,0.12);border-radius:12px;padding:1.5rem;margin:1rem 0;text-align:left}
