-.roi-out .o{background:var(--bg4);border-radius:8px;padding:0.8rem;text-align:center}
-.roi-out .o .ov{font-size:1.2rem;font-weight:800;color:var(--ac);transition:color .15s}
-.roi-out .o .ov.flash{color:#818CF8}
-.roi-out .o .ov.amber{color:var(--am)}
-.roi-out .o .ol{font-size:0.65rem;color:var(--t3);text-transform:uppercase;letter-spacing:0.5px;margin-top:0.2rem}
-.chart-wrap{max-width:700px;margin:1rem auto}.chart-wrap canvas{width:100%!important}
-.risk-box{background:rgba(251,191,36,0.04);border:1px solid rgba(251,191,36,0.1);border-radius:12px;padding:1.3rem;font-size:0.85rem;color:var(--t2);line-height:1.7;display:flex;align-items:flex-start;gap:1rem}
